/// A parsed Markdown document: the text plus its block tree.
///
/// The top-level blocks are stored with relative offsets (ADR 0006 §7.6 G1; see [`Top`]):
/// an edit shifts O(blocks / 256) chunk bases, not every following span. [`Document::blocks`]
/// is an absolute compatibility view materialised on first use after an edit (O(document));
/// hot paths use [`Document::top`] / [`Document::tops`] instead.
#[derive(Clone, Debug)]
pub struct Document {
    text: String,
    top: TopBlocks,
    /// Lazily materialised absolute copy of the top-level blocks ([`Document::blocks`]).
    abs: OnceLock<Vec<Block>>,
    /// Document-level inline context (link definitions, footnote labels), built on first use
    /// and kept across edits that touch no definition (ADR 0006 §7.4).
    ctx: OnceLock<Arc<RefContext>>,
    failed_openers: Vec<usize>,
    eol: LineEnding,
    opts: ParseOptions,
    /// Literal-line hints (ADR 0006 §2.6): editor-only; hinted lines parse as paragraph text.
    hints: HintSet,
}

/// What an [`Document::edit`] changed in the top-level block list.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EditResult {
    /// Indices (in the new block list) of the top-level blocks produced by the re-parse.
    pub new_blocks: Range<usize>,
    /// Number of old top-level blocks that were replaced.
    pub replaced: usize,
    /// Byte range of the text that was re-parsed (new coordinates).
    pub reparsed: Range<usize>,
    /// Definitions / resource root changed by the edit (ADR 0006 §7.4).
    pub deps: DepChange,
    /// Intra-line fast path (ADR 0006 §7.2.1): only the content of the leaf starting here
    /// (absolute) changed; `new_blocks` is its top-level block, re-parse was skipped.
    pub inline_leaf: Option<usize>,
    /// Nested restart (ADR 0006 §7.2.3): only the leaves from this offset (absolute, the start
    /// of the first re-parsed child) up to `reparsed.end` changed; the containers around them
    /// kept their computed state.
    pub nested_from: Option<usize>,
}

impl EditResult {
    fn none() -> Self {
        EditResult {
            new_blocks: 0..0,
            replaced: 0,
            reparsed: 0..0,
            deps: DepChange::default(),
            inline_leaf: None,
            nested_from: None,
        }
    }

    /// `self` followed by `next` as one result (block ranges united in the intermediate
    /// block list and mapped to the old / new lists).
    fn then(self, next: EditResult) -> EditResult {
        if next.replaced == 0 && next.new_blocks.is_empty() {
            let mut s = self;
            s.deps.merge(next.deps);
            return s;
        }
        let (s1, r1, n1) = (self.new_blocks.start, self.replaced, self.new_blocks.len());
        let (s2, r2, n2) = (next.new_blocks.start, next.replaced, next.new_blocks.len());
        let (start, replaced, new_len) = if r1 == 0 && n1 == 0 {
            (s2, r2, n2)
        } else if r2 == 0 && n2 == 0 {
            (s1, r1, n1)
        } else {
            let a = s1.min(s2);
            let b = (s1 + n1).max(s2 + r2);
            (a, b + r1 - n1 - a, b + n2 - r2 - a)
        };
        let reparsed = if self.reparsed.is_empty() {
            next.reparsed.clone()
        } else if next.reparsed.is_empty() {
            self.reparsed.clone()
        } else {
            self.reparsed.start.min(next.reparsed.start)..self.reparsed.end.max(next.reparsed.end)
        };
        let mut deps = self.deps;
        deps.merge(next.deps);
        EditResult {
            new_blocks: start..start + new_len,
            replaced,
            reparsed,
            deps,
            inline_leaf: None,
            nested_from: None,
        }
    }
}

/// The cached document-level inline context plus a fingerprint per reference label
/// ([`markise_doc::label_key`]; footnote labels keyed as `^label`).
#[derive(Debug, Default)]
pub struct RefContext {
    pub inline: inline::InlineContext,
    pub fingerprints: HashMap<u64, u64, std::hash::BuildHasherDefault<KeyHasher>>,
}

impl RefContext {
    fn build(doc: &Document) -> RefContext {
        let inline = inline::InlineContext {
            link_defs: doc.link_defs(),
            footnotes: doc.footnote_labels().into_iter().collect(),
        };
        let mut fingerprints =
            HashMap::with_capacity_and_hasher(inline.link_defs.len() + inline.footnotes.len(), Default::default());
        for (k, v) in &inline.link_defs {
            let mut h = fnv(&v.0);
            if let Some(t) = &v.1 {
                h = (h ^ fnv(t)).wrapping_mul(0x0100_0000_01b3) ^ 1;
            }
            fingerprints.insert(markise_doc::label_key(k), h);
        }
        for k in &inline.footnotes {
            let mut h: u64 = 0xcbf2_9ce4_8422_2325;
            for b in std::iter::once(b'^').chain(k.bytes()) {
                h = (h ^ b as u64).wrapping_mul(0x0100_0000_01b3);
            }
            fingerprints.insert(h, 1);
        }
        RefContext { inline, fingerprints }
    }
}

/// Hasher for keys that are already hashes ([`markise_doc::label_key`]).
#[derive(Default)]
pub struct KeyHasher(u64);

impl std::hash::Hasher for KeyHasher {
    fn finish(&self) -> u64 {
        self.0
    }
    fn write(&mut self, bytes: &[u8]) {
        for b in bytes {
            self.0 = (self.0 ^ *b as u64).wrapping_mul(0x0100_0000_01b3);
        }
    }
    fn write_u64(&mut self, n: u64) {
        self.0 = n;
    }
}

fn fnv(s: &str) -> u64 {
    markise_doc::label_key(s)
}

/// Appends the [`markise_doc::label_key`]s of the link reference / footnote definitions in
/// `b` (and its descendants), whose spans are relative to `origin` in `text`.
fn definition_labels(text: &str, b: &Block, origin: isize, out: &mut Vec<u64>) {
    let abs = |s: Span| Span::new((s.start as isize + origin) as usize, (s.end as isize + origin) as usize);
    b.walk(&mut |b, _| match &b.kind {
        BlockKind::LinkRefDef { label, .. } => {
            let lines: Vec<Span> = b.lines.iter().map(|l| abs(*l)).collect();
            let key = inline::normalize_label(&logical_text(text, &lines, abs(*label)));
            out.push(markise_doc::label_key(&key));
        }
        BlockKind::FootnoteDef { label } => {
            let key = inline::normalize_label(abs(*label).slice(text));
            out.push(markise_doc::label_key(&format!("^{key}")));
        }
        _ => {}
    });
}

impl Document {
    /// Parses `text` with the given options. The line ending is detected (R2.2), falling back
    /// to LF when the text contains none.
    pub fn parse(text: impl Into<String>, opts: ParseOptions) -> Self {
        Self::parse_with_default_eol(text, opts, LineEnding::Lf)
    }

    /// Like [`Document::parse`] with an explicit fallback line ending (R2.2, last bullet).
    pub fn parse_with_default_eol(text: impl Into<String>, opts: ParseOptions, default_eol: LineEnding) -> Self {
        let text = text.into();
        let eol = LineEnding::detect(&text).unwrap_or(default_eol);
        let hints = HintSet::new();
        let out = parser::parse_blocks(&text, &opts, parser::bom_len(&text), None, &hints);
        Document {
            text,
            top: TopBlocks::from_abs(out.blocks),
            abs: OnceLock::new(),
            ctx: OnceLock::new(),
            failed_openers: out.failed_openers,
            eol,
            opts,
            hints,
        }
    }

    /// A new, empty document. `prefer_final_newline` is applied by [`Document::serialize`]
    /// only for documents that were never loaded from text (R2.3).
    pub fn new_empty(opts: ParseOptions, wopts: &WriteOptions) -> Self {
        let mut d = Self::parse_with_default_eol(String::new(), opts, wopts.default_eol);
        d.eol = wopts.default_eol;
        d
    }

    pub fn text(&self) -> &str {
        &self.text
    }

    /// Top-level blocks with absolute spans: a compatibility view materialised on first use
    /// after an edit (O(document) once). Prefer [`Document::top`] / [`Document::tops`] on hot
    /// paths.
    pub fn blocks(&self) -> &[Block] {
        self.abs.get_or_init(|| self.top.to_abs_vec())
    }

    /// The document-level inline context (link definitions, footnotes) and per-label
    /// fingerprints; cached, rebuilt only after an edit that touched a definition.
    pub fn ref_context(&self) -> &Arc<RefContext> {
        self.ctx.get_or_init(|| Arc::new(RefContext::build(self)))
    }

    /// Number of top-level blocks.
    pub fn top_len(&self) -> usize {
        self.top.len()
    }

    /// Top-level block `i` with its absolute origin (spans relative to it). O(log blocks).
    pub fn top(&self, i: usize) -> Option<Top<'_>> {
        self.top.get(i)
    }

    /// The top-level blocks in order, with their absolute origins.
    pub fn tops(&self) -> impl DoubleEndedIterator<Item = Top<'_>> + '_ {
        self.top.iter()
    }

    /// An owned copy of top-level block `i` with absolute spans.
    pub fn top_block(&self, i: usize) -> Option<Block> {
        self.top.get(i).map(|t| t.to_abs())
    }

    /// Index of the first top-level block for which `pred` is false (monotone predicate).
    pub fn top_partition_point(&self, pred: impl FnMut(&Top<'_>) -> bool) -> usize {
        self.top.partition_point(pred)
    }

    pub fn options(&self) -> &ParseOptions {
        &self.opts
    }

    pub fn line_ending(&self) -> LineEnding {
        self.eol
    }

    /// `true` when the text starts with a UTF-8 byte-order mark (kept as file trivia, C35).
    pub fn has_bom(&self) -> bool {
        bom_len(&self.text) > 0
    }

    /// `true` when the text ends with a line terminator (R2.3).
    pub fn has_final_newline(&self) -> bool {
        let t = &self.text;
        t.ends_with('\n') || t.ends_with('\r') || t.ends_with(text::SYMBOL_FOR_NEWLINE)
    }

    /// Serializes the document. Because the text is the source of truth and edits are applied
    /// as patches, this is the concatenation of every block's original source and the
    /// inter-block trivia (blank lines, container prefixes) — byte-identical for an unedited
    /// document (R1.2–R1.4).
    pub fn serialize(&self) -> String {
        let mut out = String::with_capacity(self.text.len());
        let mut pos = 0;
        for t in self.top.iter() {
            let sp = t.span();
            out.push_str(&self.text[pos..sp.start]);
            out.push_str(&self.text[sp.start..sp.end]);
            pos = sp.end;
        }
        out.push_str(&self.text[pos..]);
        out
    }

    /// Switches the document line ending (menu action, R2.2): all terminators are rewritten.
    pub fn set_line_ending(&mut self, eol: LineEnding) {
        if eol == self.eol && LineEnding::detect(&self.text).is_none_or(|e| e == eol) && !self.has_mixed_eol() {
            self.eol = eol;
            return;
        }
        self.eol = eol;
        // Every offset may move: hints do not survive a full rewrite.
        self.hints = HintSet::new();
        let t = text::normalize_eol(&self.text, eol);
        let len = self.text.len();
        self.replace_all_text(t, len);
    }

    fn has_mixed_eol(&self) -> bool {
        let want = self.eol.as_str();
        let mut pos = 0;
        while pos < self.text.len() {
            let (ce, next) = text::line_end(&self.text, pos);
            if next > ce && &self.text[ce..next] != want {
                return true;
            }
            pos = next;
        }
        false
    }

    fn replace_all_text(&mut self, t: String, _old_len: usize) {
        if !self.hints.is_empty() {
            let keep = self
                .hints
                .iter()
                .copied()
                .filter(|h| h.line <= t.len() && line_start(&t, h.line) == h.line);
            self.hints = HintSet::from_hints(keep);
        }
        let out = parser::parse_blocks(&t, &self.opts, parser::bom_len(&t), None, &self.hints);
        self.text = t;
        self.top = TopBlocks::from_abs(out.blocks);
        self.abs = OnceLock::new();
        self.ctx = OnceLock::new();
        self.failed_openers = out.failed_openers;
    }

    /// Re-parses everything with new options (e.g. a syntax preference changed).
    pub fn set_options(&mut self, opts: ParseOptions) {
        self.opts = opts;
        let t = std::mem::take(&mut self.text);
        let len = t.len();
        self.replace_all_text(t, len);
    }

    /// Replaces `range` with `insert` and re-parses incrementally. Line terminators in
    /// `insert` are converted to the document's line ending (R2.2).
    ///
    /// # Panics
    /// When `range` is out of bounds or not on `char` boundaries.
    pub fn edit(&mut self, range: Range<usize>, insert: &str) -> EditResult {
        let insert = if text::count_terminators(insert) > 0 {
            text::normalize_eol(insert, self.eol)
        } else {
            insert.to_string()
        };
        self.edit_verbatim(range, &insert)
    }

    /// Like [`Document::edit`], but inserts `insert` byte-for-byte: line terminators are not
    /// converted. For callers that replace a region with text that already carries the
    /// document's original terminators (e.g. a source-mode buffer), so unchanged line endings
    /// of a mixed-ending file survive (C23).
    ///
    /// # Panics
    /// When `range` is out of bounds or not on `char` boundaries.
    pub fn edit_verbatim(&mut self, range: Range<usize>, insert: &str) -> EditResult {
        self.edit_core(range, insert, None, None)
    }

    /// Applies a patch set (ADR 0006 §2.1): one text change over the range covering all
    /// patches, one incremental re-parse. Hints are transformed through the precise patches.
    ///
    /// # Panics
    /// When the set is not valid for the current text.
    pub fn apply_patches(&mut self, ps: &PatchSet) -> EditResult {
        self.apply_patches_with_hints(ps, None)
    }

    /// Applies a patch set and installs `hints` (the complete hint set after the edit)
    /// atomically: hints on the edited lines are in place before the re-parse, so e.g. the
    /// keystroke completing an unclosed fence on a hinted line never parses the document
    /// suffix as code first (ADR 0006 §2.6). Hint changes elsewhere are re-projected after.
    ///
    /// # Panics
    /// When the set is not valid for the current text.
    pub fn apply_patches_with_hints(&mut self, ps: &PatchSet, hints: Option<&HintSet>) -> EditResult {
        if let Err(e) = ps.validate(&self.text) {
            panic!("invalid patch set: {e}");
        }
        let r = match ps.patches() {
            [] => EditResult::none(),
            [p] => self.edit_core(p.range.clone(), &p.insert, Some(ps), hints),
            _ => {
                let cover = ps.covering_range().unwrap();
                let mut new = String::with_capacity((cover.len() as isize + ps.delta()).max(0) as usize);
                let mut pos = cover.start;
                for p in ps.patches() {
                    new.push_str(&self.text[pos..p.range.start]);
                    new.push_str(&p.insert);
                    pos = p.range.end;
                }
                self.edit_core(cover, &new, Some(ps), hints)
            }
        };
        match hints {
            Some(h) if h != &self.hints => {
                let r2 = self.set_hints(h);
                r.then(r2)
            }
            _ => r,
        }
    }

    /// Canonical form of `ps` (ADR 0006 §2.1): line terminators in non-verbatim inserts are
    /// converted to the document's line ending exactly as [`Document::edit`] does (R2.2, R2.4);
    /// every patch is marked verbatim.
    pub fn canonicalize_patches(&self, ps: &PatchSet) -> PatchSet {
        let eol = self.eol;
        ps.canonical_with(|s| text::normalize_eol(s, eol), |s| text::count_terminators(s) > 0)
    }

    /// The literal-line hints.
    pub fn hints(&self) -> &HintSet {
        &self.hints
    }

    /// Replaces the hint set; re-parses the region of the lines whose hint changed (no text
    /// change). Hints not at a line start are ignored.
    pub fn set_hints(&mut self, hints: &HintSet) -> EditResult {
        let text = &self.text;
        let valid = HintSet::from_hints(hints.iter().copied().filter(|h| {
            h.line <= text.len()
                && h.from() <= text.len()
                && text.is_char_boundary(h.line)
                && text.is_char_boundary(h.from())
                && line_start(text, h.line) == h.line
        }));
        let changed = self.hints.changed_lines(&valid);
        self.hints = valid;
        let (Some(&lo), Some(&hi)) = (changed.first(), changed.last()) else {
            return EditResult::none();
        };
        let (hi_end, _) = text::line_end(&self.text, hi);
        let same = self.text[lo..hi_end].to_string();
        self.edit_core(lo..hi_end, &same, Some(&PatchSet::empty()), None)
    }

    fn edit_core(
        &mut self,
        range: Range<usize>,
        insert: &str,
        hint_ps: Option<&PatchSet>,
        final_hints: Option<&HintSet>,
    ) -> EditResult {
        let insert = insert.to_string();
        assert!(range.start <= range.end && range.end <= self.text.len());
        assert!(self.text.is_char_boundary(range.start) && self.text.is_char_boundary(range.end));

        // 0. Intra-line fast path (ADR 0006 §7.2.1): a text change inside one content line of
        //    a paragraph/heading that cannot change any block structure.
        if final_hints.is_none()
            && insert != self.text[range.clone()]
            && let Some((top, leaf_start)) = self.fast_path_target(&range, &insert)
        {
            return self.apply_fast(top, leaf_start, range, &insert, hint_ps);
        }

        // 1. Restart point: last clean top-level block starting at or before the edit (and
        //    before any failed math/front-matter opener that the edit might complete).
        let mut anchor = range.start;
        if let Some(&fo) = self.failed_openers.iter().find(|&&f| f < range.start) {
            anchor = anchor.min(fo);
        }
        let mut start_idx = 0;
        let mut from = 0;
        let mut upto = self.top.partition_point(|t| t.start() <= anchor);
        'restart: loop {
            for i in (0..upto).rev() {
                if let Some(ls) = self.top.get(i).and_then(|t| t.clean_line()) {
                    start_idx = i;
                    from = ls;
                    // R3.14.2: a block re-parsed as HTML right after an HTML block merges into
                    // it, so restart before an adjacent HTML predecessor
                    if i > 0
                        && let Some(prev) = self.top.get(i - 1)
                        && matches!(prev.block.kind, BlockKind::HtmlBlock)
                        && text::count_terminators(&self.text[prev.end()..ls]) <= 1
                    {
                        (upto, start_idx, from) = (i, 0, 0);
                        continue 'restart;
                    }
                    break 'restart;
                }
            }
            break;
        }
        let old_bom = bom_len(&self.text);
        if upto == 0 {
            start_idx = 0;
            from = old_bom;
        }
        from = from.max(old_bom);

        // 1b. Nested restart inside a large top-level container (ADR 0006 §7.2.3).
        if let Some(r) = self.edit_nested(&range, &insert, anchor, hint_ps, final_hints) {
            return r;
        }

        // The resource root lives in the first block: remember it when that may change.
        let old_root = (start_idx == 0).then(|| frontmatter::resource_root(self));
        // Definition labels of the old blocks the edit overlaps, read before their text
        // changes (old blocks after the edit are read after it, shifted: their text is intact).
        let pre_end = self.top.partition_point(|t| t.start() <= range.end);
        let mut labels: Vec<u64> = Vec::new();
        for t in self.top.range(start_idx..pre_end.max(start_idx)) {
            definition_labels(&self.text, t.block, t.origin as isize, &mut labels);
        }

        // 2. Apply the text change.
        self.abs = OnceLock::new();
        let delta = insert.len() as isize - range.len() as isize;
        let new_edit_end = range.start + insert.len();
        let old_hints = self.apply_text_change(&range, &insert, hint_ps, final_hints);

        // An edit touching the byte-order mark changes where the document starts (C35).
        if range.start < old_bom || bom_len(&self.text) != old_bom {
            let old_count = self.top.len();
            let t = std::mem::take(&mut self.text);
            let len = t.len();
            self.replace_all_text(t, len);
            return EditResult {
                new_blocks: 0..self.top.len(),
                replaced: old_count,
                reparsed: 0..self.text.len(),
                deps: DepChange::all(),
                inline_leaf: None,
                nested_from: None,
            };
        }
        self.reparse_from(
            range,
            delta,
            new_edit_end,
            old_hints,
            start_idx,
            from,
            labels,
            pre_end,
            old_root,
        )
    }

    /// Replaces `range` with `insert` and transforms the hints (installing `final_hints` of the
    /// edited lines); returns the hints before the change.
    pub(crate) fn apply_text_change(
        &mut self,
        range: &Range<usize>,
        insert: &str,
        hint_ps: Option<&PatchSet>,
        final_hints: Option<&HintSet>,
    ) -> HintSet {
        self.text.replace_range(range.clone(), insert);
        let old_hints = self.hints.clone();
        if !self.hints.is_empty() {
            let single;
            let ps = match hint_ps {
                Some(ps) => ps,
                None => {
                    single = PatchSet::single_verbatim(range.clone(), insert);
                    &single
                }
            };
            let t = &self.text;
            self.hints = self.hints.transform(ps, |o| o <= t.len() && line_start(t, o) == o);
        }
        if let Some(f) = final_hints {
            // Final hints of the edited lines take effect in this very re-parse.
            let t = &self.text;
            let lo = line_start(t, range.start);
            let hi = range.start + insert.len();
            let is_ls = |o: usize| o <= t.len() && t.is_char_boundary(o) && line_start(t, o) == o;
            let mixed = self
                .hints
                .iter()
                .filter(|h| h.line < lo || h.line > hi)
                .chain(f.iter().filter(|h| h.line >= lo && h.line <= hi && is_ls(h.line)))
                .copied();
            self.hints = HintSet::from_hints(mixed);
        }
        old_hints
    }

    /// Step 3 of [`Document::edit_core`]: re-parse from top-level block `start_idx`.
    #[allow(clippy::too_many_arguments)]
    fn reparse_from(
        &mut self,
        range: Range<usize>,
        delta: isize,
        new_edit_end: usize,
        old_hints: HintSet,
        start_idx: usize,
        from: usize,
        mut labels: Vec<u64>,
        pre_end: usize,
        old_root: Option<Option<String>>,
    ) -> EditResult {
        // 3. Re-parse until re-synchronised with an old clean block after the edit.
        let blocks = &self.top;
        let text = &self.text;
        let hints = &self.hints;
        let old_edit_end = range.end;
        let find_old = |pos: usize| -> Option<usize> {
            if pos < new_edit_end {
                return None;
            }
            let old_pos = (pos as isize - delta) as usize;
            if old_pos < old_edit_end {
                return None;
            }
            let j = blocks.partition_point(|b| b.start() < old_pos);
            let b = blocks.get(j)?;
            // The old block must start on exactly this physical line (same line start, hence the
            // same indentation, which lies after the edit and is unchanged).
            if j <= start_idx || b.clean_line() != Some(old_pos) {
                return None;
            }
            // A line whose literal hint appeared or disappeared (ADR 0006 §2.6) must be re-parsed.
            if hints.get(pos).map(|h| h.col) != old_hints.get(old_pos).map(|h| h.col) {
                return None;
            }
            Some(j)
        };
        let sync = |pos: usize| find_old(pos).is_some();
        let out = parser::parse_blocks(text, &self.opts, from, Some(&sync), &self.hints);
        let (resume_idx, reparsed_end) = match out.stopped_at {
            Some(pos) => (find_old(pos).unwrap(), pos),
            None => (self.top.len(), self.text.len()),
        };
        let new_count = out.blocks.len();
        let replaced = resume_idx - start_idx;
        // Dependencies (ADR 0006 §7.4): a definition among the replaced or the new blocks
        // may change reference resolution; a new first block may change the resource root.
        // (a superset of the labels whose definition changed: every definition among the
        // replaced and the new blocks; the context is rebuilt lazily on next use)
        for t in self.top.range(pre_end.max(start_idx)..resume_idx) {
            definition_labels(&self.text, t.block, t.origin as isize + delta, &mut labels);
        }
        for b in &out.blocks {
            definition_labels(&self.text, b, 0, &mut labels);
        }
        // Relative storage: the tail shifts by updating chunk origins only (G1).
        self.top.splice(start_idx..resume_idx, out.blocks, delta);
        let mut deps = DepChange::default();
        if !labels.is_empty() {
            labels.sort_unstable();
            labels.dedup();
            deps.labels = labels;
            self.ctx = OnceLock::new();
        }
        if let Some(old) = old_root {
            deps.resources = old != frontmatter::resource_root(self);
        }

        // failed openers: keep before `from`, add new, shift those after the resync point
        let old_resume = (reparsed_end as isize - delta) as usize;
        let mut fo: Vec<usize> = self.failed_openers.iter().copied().filter(|&f| f < from).collect();
        fo.extend(out.failed_openers.iter().copied().filter(|&f| f < reparsed_end));
        if out.stopped_at.is_some() {
            fo.extend(
                self.failed_openers
                    .iter()
                    .filter(|&&f| f >= old_resume)
                    .map(|&f| (f as isize + delta) as usize),
            );
        }
        fo.sort_unstable();
        fo.dedup();
        self.failed_openers = fo;

        EditResult {
            new_blocks: start_idx..start_idx + new_count,
            replaced,
            reparsed: from..reparsed_end,
            deps,
            inline_leaf: None,
            nested_from: None,
        }
    }

    /// The top-level block index and leaf start of an edit eligible for the intra-line fast
    /// path, if any. The rule ("line signature unchanged", conservative): the replaced and the
    /// inserted text hold no line terminator, `|`, backslash or `#` (table cell counts, escaped
    /// pipes and ATX closing sequences stay as they are); the edit lies inside one content line
    /// of a paragraph or heading, strictly after that line's first non-blank character, which
    /// is a letter (so the line starts no block — no list, quote, fence, table delimiter,
    /// setext underline, thematic break, HTML, math, front-matter or definition syntax — before
    /// or after the edit, and is no closer candidate of a failed opener); the leaf's first line
    /// also starts with a letter (no link reference definition can form); the line has no pipe
    /// (no table header candidate) and no `#` (no ATX closing sequence) and the edit does not follow a backslash; the line keeps its trailing blank run (hard breaks, content spans).
    fn fast_path_target(&self, range: &Range<usize>, insert: &str) -> Option<(usize, usize)> {
        let removed = &self.text[range.clone()];
        let breaks = |s: &str| s.contains(['\n', '\r']) || s.contains(text::SYMBOL_FOR_NEWLINE);
        if breaks(removed) || breaks(insert) {
            return None;
        }
        let bad = |s: &str| s.contains(['|', '#', '\\']);
        let i = self.top.partition_point(|t| t.end() < range.start);
        let t = self.top.get(i)?;
        if t.start() > range.start || range.end > t.end() {
            return None;
        }
        // descend (relative offsets) to the leaf containing the edit
        let (ra, rb) = (range.start - t.origin, range.end - t.origin);
        let mut b = t.block;
        while b.is_container() {
            // children are ordered and disjoint: binary search (a huge list has 10⁵ items)
            let k = b.children.partition_point(|c| c.span.start <= ra);
            let fits = |c: &&Block| c.span.start <= ra && rb <= c.span.end;
            b = k
                .checked_sub(2)
                .and_then(|j| b.children.get(j))
                .filter(fits)
                .or_else(|| k.checked_sub(1).and_then(|j| b.children.get(j)).filter(fits))?;
        }
        if matches!(
            b.kind,
            BlockKind::FencedCode { .. } | BlockKind::IndentedCode | BlockKind::MathBlock { .. }
        ) {
            return self
                .fast_path_code(t, b, ra, rb)
                .then_some((i, t.origin + b.span.start));
        }
        if !matches!(b.kind, BlockKind::Paragraph | BlockKind::Heading { .. }) || bad(removed) || bad(insert) {
            return None;
        }
        let starts_with_letter = |l: &Span| {
            let s = &self.text[t.origin + l.start..t.origin + l.end];
            s.trim_start().chars().next().is_some_and(char::is_alphabetic)
        };
        if !b.lines.first().is_some_and(starts_with_letter) {
            return None;
        }
        let l = b.lines.iter().find(|l| l.start <= ra && rb <= l.end)?;
        if !starts_with_letter(l) {
            return None;
        }
        let line = &self.text[t.origin + l.start..t.origin + l.end];
        let (a, z) = (ra - l.start, rb - l.start);
        let lead = line.len() - line.trim_start().len();
        let first_len = line[lead..].chars().next()?.len_utf8();
        // after the first character, and not right after a backslash (the edit would change
        // what it escapes, e.g. un-escape a pipe)
        // a line with a pipe may be a table header candidate: its cell count depends on the
        // text around the pipes
        // (and a `#` may end an ATX heading's content as a closing sequence)
        if a < lead + first_len || line[..a].ends_with('\\') || line.contains(['|', '#']) {
            return None;
        }
        let trail = |s: &str| s.len() - s.trim_end().len();
        let new_line = format!("{}{insert}{}", &line[..a], &line[z..]);
        if z > line.trim_end().len() || trail(line) != trail(&new_line) {
            return None;
        }
        Some((i, t.origin + b.span.start))
    }

    /// The fast-path rule for a content line of a code or math block (no line break in the
    /// edit, checked by the caller): the edit lies after the line's first non-blank character,
    /// and neither that character nor the first non-blank character of the physical line is a
    /// fence (`` ` ``, `~`) or math (`$`, `\`) delimiter character — so the line is not and
    /// does not become a closing line (of this block, or of a failed opener whose look-ahead
    /// spans it), and its indentation (indented code, container prefixes) is unchanged. Code
    /// content keeps trailing blanks, so they need no check.
    fn fast_path_code(&self, t: Top<'_>, b: &Block, ra: usize, rb: usize) -> bool {
        let Some(l) = b.lines.iter().find(|l| l.start <= ra && rb <= l.end) else {
            return false;
        };
        let delim = |c: char| matches!(c, '`' | '~' | '$' | '\\');
        let line = &self.text[t.origin + l.start..t.origin + l.end];
        let lead = line.len() - line.trim_start().len();
        let Some(first) = line[lead..].chars().next() else {
            return false;
        };
        let phys_start = line_start(&self.text, t.origin + l.start);
        let phys = &self.text[phys_start..t.origin + l.end];
        let phys_first = phys.trim_start().chars().next();
        ra - l.start >= lead + first.len_utf8() && !delim(first) && !phys_first.is_some_and(delim)
    }

    /// Applies an edit accepted by [`Document::fast_path_target`]: text, hints, the spans of
    /// the enclosing top-level block (stretched in place) and the origins after it.
    fn apply_fast(
        &mut self,
        top: usize,
        leaf_start: usize,
        range: Range<usize>,
        insert: &str,
        hint_ps: Option<&PatchSet>,
    ) -> EditResult {
        self.abs = OnceLock::new();
        let delta = insert.len() as isize - range.len() as isize;
        self.text.replace_range(range.clone(), insert);
        if !self.hints.is_empty() {
            let single;
            let ps = match hint_ps {
                Some(ps) => ps,
                None => {
                    single = PatchSet::single_verbatim(range.clone(), insert);
                    &single
                }
            };
            let t = &self.text;
            self.hints = self.hints.transform(ps, |o| o <= t.len() && line_start(t, o) == o);
        }
        let origin = self.top.get(top).map_or(0, |t| t.origin);
        if let Some(b) = self.top.get_mut(top) {
            b.stretch(range.end - origin, delta);
        }
        self.top.shift_after(top, delta);
        for f in &mut self.failed_openers {
            if *f > range.start {
                *f = (*f as isize + delta) as usize;
            }
        }
        let end = self.top.get(top + 1).map_or(self.text.len(), |t| t.origin);
        EditResult {
            new_blocks: top..top + 1,
            replaced: 1,
            reparsed: origin..end,
            deps: DepChange::default(),
            inline_leaf: Some(leaf_start),
            nested_from: None,
        }
    }

    /// Path of indices from the top level down to the deepest block containing `pos`.
    pub fn block_path_at(&self, pos: usize) -> Vec<usize> {
        let mut path = Vec::new();
        let i = self.top.partition_point(|t| t.end() < pos);
        let Some(t) = self.top.get(i).filter(|t| t.start() <= pos) else {
            return path;
        };
        path.push(i);
        // inside the top-level block, offsets are relative to its origin
        let pos = pos - t.origin;
        let mut list = &t.block.children;
        loop {
            let i = list.partition_point(|b| b.span.end < pos);
            match list.get(i) {
                Some(b) if b.span.start <= pos => {
                    path.push(i);
                    list = &b.children;
                }
                _ => break,
            }
        }
        path
    }

    /// Resolves a block path produced by [`Document::block_path_at`]: an owned copy of that
    /// block (and its descendants) with absolute spans.
    pub fn block_at_path(&self, path: &[usize]) -> Option<Block> {
        let (r, origin) = self.block_at_path_rel(path)?;
        let mut b = r.clone();
        b.shift(origin as isize);
        Some(b)
    }

    /// Like [`Document::block_at_path`] without copying: the block with spans relative to the
    /// returned origin (add it to every span).
    pub fn block_at_path_rel(&self, path: &[usize]) -> Option<(&Block, usize)> {
        let (&first, rest) = path.split_first()?;
        let t = self.top.get(first)?;
        let mut cur = t.block;
        for &i in rest {
            cur = cur.children.get(i)?;
        }
        Some((cur, t.origin))
    }

    /// Link reference definitions (normalised label → (destination, title)), first one wins.
    pub fn link_defs(&self) -> HashMap<String, (String, Option<String>)> {
        let mut map = HashMap::new();
        for t in self.top.iter() {
            t.block.walk(&mut |b, _| {
                if let BlockKind::LinkRefDef { .. } = &b.kind {
                    let mut b = b.clone();
                    b.shift(t.origin as isize);
                    let BlockKind::LinkRefDef { label, dest, title } = &b.kind else {
                        unreachable!()
                    };
                    // Labels and titles may span lines: use the logical content of the lines
                    // (container prefixes such as `> ` excluded), not the raw source span.
                    let key = inline::normalize_label(&logical_text(&self.text, &b.lines, *label));
                    map.entry(key).or_insert_with(|| {
                        let d = dest.slice(&self.text);
                        let d = d.strip_prefix('<').and_then(|d| d.strip_suffix('>')).unwrap_or(d);
                        let t = title.map(|t| {
                            let s = logical_text(&self.text, &b.lines, t);
                            let mut it = s.chars();
                            it.next();
                            it.next_back();
                            it.as_str().to_string()
                        });
                        (inline::unescape(d), t.map(|t| inline::unescape(&t)))
                    });
                }
            });
        }
        map
    }

    /// Footnote labels in definition order (normalised).
    pub fn footnote_labels(&self) -> Vec<String> {
        let mut v = Vec::new();
        for t in self.top.iter() {
            t.block.walk(&mut |b, _| {
                if let BlockKind::FootnoteDef { label } = &b.kind {
                    v.push(inline::normalize_label(t.abs(*label).slice(&self.text)));
                }
            });
        }
        v
    }

    /// Checks internal invariants (spans ordered, inside the text). Used by tests.
    pub fn validate(&self) -> Result<(), String> {
        let mut pos = 0;
        for (i, t) in self.top.iter().enumerate() {
            let sp = t.span();
            if sp.start < pos || sp.end < sp.start || sp.end > self.text.len() {
                return Err(format!("block {i} span {sp:?} out of order (prev end {pos})"));
            }
            pos = sp.end;
        }
        Ok(())
    }
}

/// Text of `span` restricted to the content `lines` (joined with `\n`), i.e. without the
/// container prefixes between lines.
fn logical_text(text: &str, lines: &[Span], span: Span) -> String {
    let mut out = String::new();
    let mut first = true;
    for l in lines {
        let s = l.start.max(span.start);
        let e = l.end.min(span.end);
        if s >= e {
            continue;
        }
        if !first {
            out.push('\n');
        }
        first = false;
        out.push_str(&text[s..e]);
    }
    if first {
        return span.slice(text).to_string();
    }
    out
}

/// Start of the line containing `pos`.
pub(crate) fn line_start(text: &str, pos: usize) -> usize {
    let b = text.as_bytes();
    let mut p = pos;
    while p > 0 {
        let c = b[p - 1];
        if c == b'\n' || c == b'\r' {
            break;
        }
        if c == 0xA4 && p >= 3 && &b[p - 3..p] == "\u{2424}".as_bytes() {
            break;
        }
        p -= 1;
    }
    p
}

/// Convenience: parse with default options.
pub fn parse(text: &str) -> Document {
    Document::parse(text, ParseOptions::default())
}

/// Compact textual dump of the block tree, for tests and debugging.
pub fn debug_tree(doc: &Document) -> String {
    let mut out = String::new();
    for b in doc.blocks() {
        b.walk(&mut |b, depth| {
            let name = match &b.kind {
                BlockKind::Paragraph => "para".to_string(),
                BlockKind::Heading { level, setext, .. } => {
                    format!("h{level}{}", if *setext { "s" } else { "" })
                }
                BlockKind::ThematicBreak => "hr".into(),
                BlockKind::FencedCode { info, .. } => format!("fence[{}]", info.slice(doc.text())),
                BlockKind::IndentedCode => "icode".into(),
                BlockKind::MathBlock { .. } => "math".into(),
                BlockKind::HtmlBlock => "html".into(),
                BlockKind::Table { aligns } => format!("table{}", aligns.len()),
                BlockKind::BlockQuote { alert: None } => "quote".into(),
                BlockKind::BlockQuote { alert: Some(k) } => format!("alert-{}", k.as_str()),
                BlockKind::List { ordered, tight, .. } => {
                    format!(
                        "{}{}",
                        if *ordered { "ol" } else { "ul" },
                        if *tight { "" } else { "-loose" }
                    )
                }
                BlockKind::ListItem { task: Some((c, _)), .. } => format!("li[{}]", if *c { "x" } else { " " }),
                BlockKind::ListItem { .. } => "li".into(),
                BlockKind::FrontMatter { .. } => "fm".into(),
                BlockKind::Toc => "toc".into(),
                BlockKind::FootnoteDef { label } => format!("fn[{}]", label.slice(doc.text())),
                BlockKind::LinkRefDef { label, .. } => format!("def[{}]", label.slice(doc.text())),
            };
            out.push_str(&"  ".repeat(depth));
            out.push_str(&name);
            if !b.lines.is_empty() && !b.is_container() {
                out.push_str(&format!(" {:?}", b.content(doc.text())));
            }
            out.push('\n');
        });
    }
    out
}
